contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(msg.value >= amount);

        uint256 b0 = c.balances(address(this));
        uint256 cb0 = address(c).balance;

        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(amount > type(uint256).max - b0);
            assert(c.balances(address(this)) == b0);
            assert(address(c).balance == cb0);
        } else {
            assert(amount <= type(uint256).max - b0);
            assert(c.balances(address(this)) == b0 + amount);
            assert(address(c).balance == cb0 + amount);
        }
    }

    receive() external payable {}
}

