contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 dep, uint256 amt) public payable {
        require(address(this).balance >= dep);
        require(dep > 0);

        c.deposit{value: dep}();
        uint256 balBefore = c.balances(address(this));
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balances(address(this));
        uint256 cBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        if (reverted) {
            assert(balAfter == balBefore && cBalAfter == cBalBefore && selfBalAfter == selfBalBefore);
        } else {
            assert(balAfter == balBefore - amt && cBalAfter == cBalBefore - amt && selfBalAfter == selfBalBefore + amt && amt <= balBefore);
        }
    }

    receive() external payable {}
}

