contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public payable {
        bool reverted;
        uint256 cBalBefore = address(c).balance;
        uint256 toBalBefore = address(to).balance;
        try c.migrateTo(to) { reverted = false; } catch { reverted = true; }
        uint256 cBalAfter = address(c).balance;
        uint256 toBalAfter = address(to).balance;
        uint256 actualDiff = toBalAfter - toBalBefore;
        assert((cBalBefore != 0) || reverted);
        assert(reverted == false);
        assert(cBalAfter == 0);
        assert(actualDiff == cBalBefore);
    }
}

